<template><section class="v2-page therapist-v2-page"><div v-if="loading" class="v2-state">正在打开阶段复核…</div><div v-else-if="error" class="v2-state v2-state-error">{{ error }}</div><template v-else-if="review"><header class="v2-page-header"><p class="v2-context">Stage Review</p><h1>基于事实做阶段决策</h1><p>clinical_stage 仅作为正式评估的内部支撑；最终决定由治疗师确认。</p></header><section class="semantic-layers stage-review-layers"><article class="layer facts"><p class="v2-section-label">FACTS</p><h2>事实与可比较趋势</h2><div class="review-fact-list"><p v-for="trend in review.facts.trends" :key="trend.code"><strong>{{ trend.label }}</strong>{{ trend.explanation }}</p><p v-if="!review.facts.trends?.length">当前没有足够的可比较训练事实。</p></div><div class="review-source-block"><h3>正式评估</h3><p v-if="!review.formal_assessments.length">本次复核窗口没有正式评估。</p><dl v-for="item in review.formal_assessments" :key="item.id"><div><dt>{{ item.instrument_name }} · {{ item.instrument_version }}</dt><dd>{{ formatDate(item.assessed_at) }} · {{ item.review_status }}</dd></div><div><dt>已施测指标</dt><dd>{{ item.measured_metrics.length ? item.measured_metrics.join('、') : '无；缺失项已按未施测保留' }}</dd></div></dl></div><div class="review-source-block"><h3>clinical_stage 内部支撑</h3><p v-if="!review.clinical_stage_support.length">当前没有可用的内部阶段评估结果。</p><p v-for="item in review.clinical_stage_support" :key="item.id">{{ item.result_status }} · {{ item.algorithm_version }}</p></div></article><article class="layer observations"><p class="v2-section-label">SYSTEM OBSERVATIONS</p><h2>系统观察</h2><p v-if="!review.observations.length">暂无系统观察。</p><p v-for="item in review.observations" :key="item.id">{{ item.statement }}</p></article><article class="layer recommendations"><p class="v2-section-label">CANDIDATE RECOMMENDATIONS</p><h2>候选建议</h2><p v-if="!review.recommendations.length">当前没有候选建议；这不会阻止治疗师做决定。</p><p v-for="item in review.recommendations" :key="item.id">{{ item.candidate_action }}</p></article><article class="layer decision"><p class="v2-section-label">THERAPIST DECISION</p><h2>专业决定</h2><form v-if="review.status!=='finalized'" class="decision-form" @submit.prevent="decide"><label>决定<select v-model="form.decision_type"><option value="continue_current_plan">继续当前方案</option><option value="create_new_training_plan_version">创建新方案版本</option><option value="request_formal_assessment">安排正式评估</option><option value="no_action">暂不调整</option><option value="add_clinical_note">添加专业记录</option></select></label><label>理由<textarea v-model="form.reason" required></textarea></label><label v-if="form.decision_type==='create_new_training_plan_version'">新的阶段重点<input v-model="form.stage_focus"/></label><button class="v2-button primary" :disabled="busy">确认治疗师决定</button></form><div v-else class="v2-inline-success">阶段复核已经形成正式决定。若创建了方案草稿，仍需在“训练方案”中正式发布。</div></article></section></template></section></template>
<script setup lang="ts">import { onMounted,reactive,ref } from 'vue';import { useRoute } from 'vue-router';import { v2Api } from '@/api/v2';import { toUserMessage } from '@/utils/errors';const route=useRoute();const review=ref<any>(null);const loading=ref(true);const busy=ref(false);const error=ref('');const form=reactive({decision_type:'continue_current_plan',reason:'',stage_focus:''});async function load(){try{review.value=await v2Api.stageReview(String(route.params.reviewId))}catch(err){error.value=toUserMessage(err,'阶段复核加载失败。')}finally{loading.value=false}}async function decide(){busy.value=true;error.value='';try{const sourceAttention=String(route.query.attention||'');await v2Api.createDecision(review.value.id,{decision_type:form.decision_type,reason:form.reason,source_attention_item_id:sourceAttention||null,payload:form.stage_focus?{stage_focus:form.stage_focus}:{}});await load()}catch(err){error.value=toUserMessage(err,'决定保存失败。')}finally{busy.value=false}}function formatDate(value:string){return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}onMounted(load);</script>
